import numpy as npimport pandas as pdimport matplotlib.pyplot as pltfrom sklearn.model_selection import train_test_splitfrom sklearn.preprocessing import StandardScalerfrom sklearn.preprocessing import LabelEncoderfrom sklearn.linear_model import LogisticRegressionfrom matplotlib.colors import ListedColormapfrom sklearn.metrics import accuracy_scorefrom sklearn.tree import DecisionTreeClassifierfrom sklearn import treedef plot_decision_regions(X, y, classifier, test_idx=None,                          resolution=0.02):    # Setup marker generator and color map    markers = ('o', 's', '^', 'v', '<')    colors = ('red', 'blue', 'lightgreen', 'gray', 'cyan')    cmap = ListedColormap(colors[:len(np.unique(y))])        # Plot the decision surface    x1_min, x1_max = X[:, 0].min() - 1, X[:, 0].max() + 1    x2_min, x2_max = X[:, 1].min() - 1, X[:, 1].max() + 1    xx1, xx2 = np.meshgrid(np.arange(x1_min, x1_max, resolution),                           np.arange(x2_min, x2_max, resolution))        # Make predictions on the grid points and convert to integers    Z = classifier.predict(np.array([xx1.ravel(), xx2.ravel()]).T)    Z = Z.astype(int)  # Ensure numeric values for contourf    Z = Z.reshape(xx1.shape)        plt.contourf(xx1, xx2, Z, alpha=0.3, cmap=cmap)    plt.xlim(xx1.min(), xx1.max())    plt.ylim(xx2.min(), xx2.max())        # Plot class examples    for idx, cl in enumerate(np.unique(y)):        plt.scatter(x=X[y == cl, 0],                    y=X[y == cl, 1],                    alpha=0.8,                    c=colors[idx],                    marker=markers[idx],                    label=f'Class {cl} ({le.inverse_transform([cl])[0]})',  # Show original label                    edgecolor='black')        # Highlight test examples    if test_idx:        X_test, y_test = X[test_idx, :], y[test_idx]        plt.scatter(X_test[:, 0], X_test[:, 1],                    c='none', edgecolor='black', alpha=1.0,                    linewidth=1, marker='o',                    s=100, label='Test set')#read excelclownfish_data = pd.read_excel('/Users/ggraham/Desktop/multiome_poa/Reference/Complete Data Frame (Hormones, Behavior, Size, Gonads) GG.xlsx')#extract just male and femaleclownfish_data_known_sex = clownfish_data[(clownfish_data['Status'].isin(['M','F']))]clownfish_data_unknown_sex= clownfish_data[(clownfish_data['Status']!= 'M')&(clownfish_data['Status']!= 'F') ]#select factorsclown_x = clownfish_data_known_sex[['mass_final_cm','Log_11KT']]clown_x_unknown = clownfish_data_unknown_sex[['mass_final_cm','Log_11KT']]#fill in  gapsclown_x['Log_11KT'][9] = clownfish_data_known_sex['Log_11KT'][clownfish_data_known_sex['Status']=='M'].mean()clown_x['Log_11KT'][8] = clownfish_data_known_sex['Log_11KT'][clownfish_data_known_sex['Status']=='F'].mean()clown_y = clownfish_data_known_sex[['Status']]    #encode labelsle = LabelEncoder()y_encoded = le.fit_transform(clown_y.values.ravel())#set male and female as trainX_train = clown_xX_test = clown_x_unknown#scale datasc = StandardScaler()sc.fit(X_train)x_train_std = sc.transform(X_train)x_test_std = sc.transform(X_test)### Decision Tree Model ###tree_model = DecisionTreeClassifier(criterion = 'gini',                                     max_depth = 4,                                     random_state=1)tree_model.fit(x_train_std, y_encoded)y_test = [0 for _ in range(len(clown_x_unknown))]X_combined_std = np.vstack((x_train_std, x_test_std))y_combined = np.hstack((y_encoded, y_test))# Plot decision regionsplot_decision_regions(X=X_combined_std,                       y=y_combined,                       classifier=tree_model,                      test_idx=range(len(y_train), len(y_combined)))# visualize treefeature_names = ['mass_final_cm','Log_11KT']tree.plot_tree(tree_model,                feature_names=feature_names,                filled=True)plt.show()#so its based basically 100% on KT?### random forestfrom sklearn.ensemble import RandomForestClassifierforest = RandomForestClassifier(n_estimators=25, random_state=1, n_jobs=2)forest.fit(X_train, y_encoded)plot_decision_regions(X_combined_std, y_combined, classifier=forest,                      test_idx=range(len(y_train), len(y_combined)))plt.show()# cant rly make this work correctly# the more I think about it I also don think this is as appropriate for my data as a logistic or SVM